using System;using System.IO;using System.Diagnostics;using System.Collections.Generic;using System.Globalization;using System.Web.Script.Serialization;using System.Linq;using ThinkPadModesV3;
internal static class GpuTemperatureChecks {
 internal static int Run(string output){var rows=new List<object>();Process p=null;string error=null;double maximum=0;try{using(var gpu=new NvmlTelemetry()){gpu.TemperatureOnly();p=Process.Start(new ProcessStartInfo(Path.Combine(Environment.SystemDirectory,"nvidia-smi.exe"),"--query-gpu=temperature.gpu --format=csv,noheader,nounits --loop-ms=500"){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true});for(int n=0;n<30;n++){string line=p.StandardOutput.ReadLine();if(line==null)throw new IOException("nvidia-smi arrêté");double smi=Double.Parse(line.Trim(),CultureInfo.InvariantCulture);var actual=gpu.TemperatureOnly();if(!actual.HasValue)throw new IOException(gpu.TemperatureError+" "+new JavaScriptSerializer().Serialize(new{Code=gpu.LastTemperatureReturn,Field=gpu.LastTemperatureField,Now=gpu.LastTemperatureNow}));double delta=Math.Abs(actual.Value-smi);maximum=Math.Max(maximum,delta);rows.Add(new{UTC=DateTime.UtcNow.ToString("o"),NvidiaSmi=smi,Application=actual.Value,Delta=delta,SourceTimestamp=gpu.TemperatureTimestamp});}if(maximum>3)throw new IOException("Écart température >3°C");}}catch(Exception e){error=e.Message;}finally{if(p!=null){if(!p.HasExited){p.Kill();p.WaitForExit();}p.Dispose();}File.WriteAllText(output,new JavaScriptSerializer().Serialize(new{UTC=DateTime.UtcNow.ToString("o"),Passed=error==null,Error=error,Count=rows.Count,MaximumDifferenceC=maximum,Source="NVML_FI_DEV_GPU_TEMP 308 · double · timestamp",Rows=rows}));}return error==null?0:1;}
}
